SELECT s.cds, s.rtype, s.sname AS sat_name, s.AvgScrMath, sc.School AS school_tbl_name, sc.MailStreet
FROM satscores s LEFT JOIN schools sc ON sc.CDSCode = s.cds
ORDER BY s.AvgScrMath DESC LIMIT 15;

SELECT s.cds, s.rtype, s.sname, s.dname, s.AvgScrRead, sc.School, sc.Phone
FROM satscores s LEFT JOIN schools sc ON sc.CDSCode = s.cds
WHERE s.cds LIKE '1062142%' ORDER BY s.AvgScrRead LIMIT 5;

SELECT COUNT(*) AS n_schools_named, SUM(CASE WHEN Street = MailStreet THEN 1 ELSE 0 END) AS same_street,
       SUM(CASE WHEN School IS NULL THEN 1 ELSE 0 END) AS unnamed
FROM schools;
